function SuperTimelineV2_15200850:OnMainInitEnd( MainForRuntime_ )

    local roleTF = MainForRuntime_.roleAnimator.transform
    local ears_BlendTF = roleTF:Find("Unity_Export_Grp/Geometry/ears_Blend")
    local hair_BlendTF = roleTF:Find("Unity_Export_Grp/Geometry/hair_Blend")
    assert( isNotNull(ears_BlendTF) and isNotNull(hair_BlendTF) )
    local ears_Render = KTool.GetComponent(ears_BlendTF.gameObject, typeof(SkinnedMeshRenderer))
    local hair_Render = KTool.GetComponent(hair_BlendTF.gameObject, typeof(SkinnedMeshRenderer))
    self.earsMat = ears_Render.material
    self.hairMat = hair_Render.material
end


-- MainForRuntime:OnSwitchStage() 的尾部被执行:
function SuperTimelineV2_15200850:OnSwitchStageEnd( MainForRuntime_, newStageJson_ )
    if isNull(self.earsMat) or isNull(self.hairMat) then 
        printError("earsMat 或 hairMat 为 nil")
        return
    end 
    ---
    local stageName = newStageJson_.stageName
    if stageName == "100" or stageName == "101" then 
        --printError("--黄色--")
        local w = 0 -- 0:黄色; 2:蓝黑色
        self.earsMat:SetFloat( "_HairBlend", w )
        self.hairMat:SetFloat( "_HairBlend", w )

    elseif stageName == "200" then 
        --printError("--蓝色--")
        local w = 2 -- 0:黄色; 2:蓝黑色
        self.earsMat:SetFloat( "_HairBlend", w )
        self.hairMat:SetFloat( "_HairBlend", w )
    end 
end




return SuperTimelineV2_15200850
